const REDUCED = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

function flat(l){
  const d=T[l], o={};
  d.nav.forEach((v,i)=>o["nav"+i]=v);
  o.navCta=d.navCta;
  ["heroTag","heroH1","heroP","heroStory","ghostWelcome","entEye","entH2","entLead",
   "entPlName","entPlLoc","entPlRole","entPlDesc","entDzName","entDzLoc","entDzRole","entDzDesc",
   "divEye","divH2","divLead","mkEye","mkH2","mkLead","mkNote",
   "prEye","prH2","flEye","flH3","flP","vaEye","vaH2",
   "ctaH2","ctaLead","ctaBtn","coEye","coH2","coLead","fName","fCompany","fEmail","fMsg","fSend",
   "ciTitle","ciPl","ciPlV","ciDz","ciDzV","ciEmail","ciPhone","ciPhoneV",
   "ftDesc","ftGroup","ftDiv","ftBiz","ftCopy","featLink",
   "presH2","presSub","liveTag","langLabel","flTag2","skipLink",
   "corrEye","corrH2","svcEye","svcH2","svcLead","svcBtn","ghostDiv","ghostQual",
   "newsEye","newsH2","newsAll","newsRead","pilEye","pilH2","pilLead","presText","presBtn"].forEach(k=>o[k]=d[k]);
  d.st.forEach((s,i)=>{o["stD"+i]=s[2];});
  d.entPlB.forEach((v,i)=>o["entPlB"+i]=v);
  d.entDzB.forEach((v,i)=>o["entDzB"+i]=v);
  d.divTags.forEach((v,i)=>o["divTag"+i]=v);
  d.divCards.forEach((c,i)=>{o["divT"+i]=c[0];o["divD"+i]=c[1];});
  d.logModes.forEach((c,i)=>{o["logT"+i]=c[0];o["corrSub"+i]=c[1].split('.')[0];});
  d.capCards.forEach((c,i)=>{o["capT"+i]=c[0];});
  d.flFeat.forEach((v,i)=>o["fl"+i]=v);
  d.news.forEach((n,i)=>{o["nwTag"+i]=n[0];o["nwTitle"+i]=n[1];o["nwText"+i]=n[2];});
  d.qualStats.forEach((q,i)=>{o["qlV"+i]=q[0];o["qlL"+i]=q[1];});
  d.pillars.forEach((c,i)=>{o["pilT"+i]=c[0];o["pilD"+i]=c[1];});
  o.qualEye=d.qualEye;o.qualH2=d.qualH2;o.qualLead=d.qualLead;
  d.ftGroupL.forEach((v,i)=>o["ftG"+i]=v);
  d.ftDivL.forEach((v,i)=>o["ftD"+i]=v);
  d.ftBizL.forEach((v,i)=>o["ftB"+i]=v);
  return o;
}

/* --- titre mot par mot --- */
function animateTitle(l){
  const h=document.getElementById('heroH1'), txt=T[l].heroH1;
  if(l==='ar'||REDUCED){ h.textContent=txt; return; }
  h.innerHTML=txt.split(' ').map(w=>'<span class="sp"><i>'+w+'</i></span>').join(' ');
  const items=[...h.querySelectorAll('i')];
  requestAnimationFrame(()=>items.forEach((el,i)=>{
    el.style.transitionDelay=(0.05+i*0.055)+'s'; el.classList.add('in');
  }));
}

