/* --- carrousel corridors --- */
const corrTrack=document.getElementById('corrTrack');
function corrStep(dir){
  const card=corrTrack.querySelector('.corr-card');
  const w=card?card.getBoundingClientRect().width+2:300;
  corrTrack.scrollBy({left:dir*w,behavior:REDUCED?'auto':'smooth'});
}
document.getElementById('corrPrev').addEventListener('click',()=>corrStep(document.documentElement.dir==='rtl'?1:-1));
document.getElementById('corrNext').addEventListener('click',()=>corrStep(document.documentElement.dir==='rtl'?-1:1));

/* --- bandeau marches --- */
function buildMarquee(l){
  const t=document.getElementById('marqTrack');
  const one=T[l].markets.map(m=>'<div class="marq-item">'+m+'</div>').join('');
  t.innerHTML=one+one;
}

let LANG="en";
function setLang(l){
  LANG=l;
  const o=flat(l);
  document.documentElement.lang=l;
  document.documentElement.dir=(l==="ar")?"rtl":"ltr";
  document.querySelectorAll("[data-i]").forEach(el=>{
    const v=o[el.dataset.i]; if(v!==undefined) el.innerHTML=v;
  });
  const d=T[l];
  document.getElementById("ph1").placeholder=d.phName;
  document.getElementById("ph2").placeholder=d.phCompany;
  document.getElementById("ph3").placeholder=d.phEmail;
  document.getElementById("ph4").placeholder=d.phMsg;
  document.getElementById("gwLang").textContent=l;
  document.querySelectorAll(".langmenu button").forEach(b=>b.classList.toggle("on",b.dataset.l===l));
  animateTitle(l); buildMarquee(l); featBuild(l);
}

function detect(){
  try{ if((Intl.DateTimeFormat().resolvedOptions().timeZone||"")==="Europe/Warsaw") return "pl"; }catch(e){}
  const s=(navigator.languages||[navigator.language||"en"]).join(",").toLowerCase();
  if(s.startsWith("pl")||s.includes(",pl")) return "pl";
  if(s.startsWith("ar")) return "ar";
  if(s.startsWith("fr")) return "fr";
  return "en";
}

document.querySelector('.langmenu').addEventListener('click',e=>{
  const b=e.target.closest('button'); if(b&&b.dataset.l) setLang(b.dataset.l);
});

const burger=document.getElementById("burger"), navLinks=document.getElementById("navLinks");
function setBurger(open){
  navLinks.classList.toggle("open",open); burger.classList.toggle("x",open);
  burger.setAttribute("aria-expanded",open?"true":"false");
}
burger.addEventListener("click",()=>setBurger(!navLinks.classList.contains("open")));
navLinks.querySelectorAll("a").forEach(a=>a.addEventListener("click",()=>setBurger(false)));

const langWrap=document.getElementById("langWrap"), langBtn=document.getElementById("langBtn");
langBtn.addEventListener("click",e=>{
  e.preventDefault();
  const open=!langWrap.classList.contains("open");
  langWrap.classList.toggle("open",open); langBtn.setAttribute("aria-expanded",open?"true":"false");
});
document.addEventListener("click",e=>{
  if(!langWrap.contains(e.target)){ langWrap.classList.remove("open"); langBtn.setAttribute("aria-expanded","false"); }
});
document.addEventListener("keydown",e=>{
  if(e.key==="Escape"){
    langWrap.classList.remove("open"); langBtn.setAttribute("aria-expanded","false");
    if(document.activeElement && langWrap.contains(document.activeElement)) document.activeElement.blur();
    setBurger(false);
  }
});

const secs=["corridors","group","divisions","news","entities"].map(id=>document.getElementById(id));
const links=[...navLinks.querySelectorAll("a")];
const heroBg=document.getElementById('heroBg'), prog=document.getElementById('prog'), toTop=document.getElementById('toTop');
toTop.addEventListener("click",()=>window.scrollTo({top:0,behavior:REDUCED?"auto":"smooth"}));
let ticking=false;
window.addEventListener('scroll',()=>{
  if(ticking) return; ticking=true;
  requestAnimationFrame(()=>{
    const y=window.scrollY;
    if(!REDUCED && y<1000) heroBg.style.transform='translateY('+(y*0.16)+'px)';
    const max=document.documentElement.scrollHeight-window.innerHeight;
    prog.style.width=(max>0?(y/max*100):0)+'%';
    toTop.classList.toggle("show",y>640);
    let cur=0; secs.forEach((s,i)=>{ if(s && s.getBoundingClientRect().top<200) cur=i; });
    links.forEach((a,i)=>a.classList.toggle("on",i===cur));
    ticking=false;
  });
},{passive:true});

const io=new IntersectionObserver(es=>es.forEach(en=>{
  if(en.isIntersecting){ en.target.classList.add("in"); io.unobserve(en.target); }
}),{threshold:.1});
document.querySelectorAll(".reveal,.stag,.hero-tag").forEach(el=>io.observe(el));

const cio=new IntersectionObserver(es=>es.forEach(en=>{
  if(!en.isIntersecting) return;
  const el=en.target, t=+el.dataset.target, suf=el.dataset.suffix||'';
  if(REDUCED){ el.textContent=t+suf; cio.unobserve(el); return; }
  const dur=1100, t0=performance.now();
  (function step(now){
    const p=Math.min(1,(now-t0)/dur), e=1-Math.pow(1-p,3);
    el.textContent=Math.round(t*e)+suf;
    if(p<1) requestAnimationFrame(step);
  })(performance.now());
  cio.unobserve(el);
}),{threshold:.5});
document.querySelectorAll('.cnt').forEach(el=>cio.observe(el));

document.querySelectorAll('.tilt').forEach(card=>{
  card.addEventListener('mousemove',e=>{
    const r=card.getBoundingClientRect();
    card.style.setProperty('--mx',(e.clientX-r.left)+'px');
    card.style.setProperty('--my',(e.clientY-r.top)+'px');
  });
});

if(!REDUCED){
  document.querySelectorAll('.mag').forEach(btn=>{
    btn.addEventListener('mousemove',e=>{
      const r=btn.getBoundingClientRect();
      const dx=(e.clientX-(r.left+r.width/2))/r.width, dy=(e.clientY-(r.top+r.height/2))/r.height;
      btn.style.transform='translate('+(dx*7).toFixed(1)+'px,'+(dy*5).toFixed(1)+'px)';
    });
    btn.addEventListener('mouseleave',()=>{ btn.style.transform=''; });
  });
}

document.getElementById("cform").addEventListener("submit",e=>{
  e.preventDefault();
  e.target.querySelector(".btn span").textContent=T[LANG].fThanks;
});

setLang(detect());
